    # ET.tostring returns bytes in py3; handle
    try:
        return ET.tostring(e, encoding='unicode')
    except Exception:
        return ''

def elem_text(e):
    # return concatenated text
    texts = []
    if e.text:
        texts.append(e.text)
    for c in e:
        texts.append(elem_text(c))
        if c.tail:
            texts.append(c.tail)
    return ''.join([t for t in texts if t])

def css_to_xpath(selector):
    # Very naive conversion: support tag, descendant (space) and child (>), and attribute [attr=value]
    s = selector.strip()
    # Replace > with /
    s = s.replace(' > ', '/')
    parts = s.split()
    xpath = '.'
    for i, part in enumerate(parts):
        if '/' in part:
            # child chain
            subparts = part.split('/')
            for sp in subparts:
                if sp:
                    xpath += '/' + sp
        else:
            xpath += '//' + part
    return xpath

