    xpath = css_to_xpath(selector)
    try:
        return root.findall(xpath)
    except Exception:
        # fallback: try simple tag
        return root.findall('.//' + selector)

def elem_to_json(e, depth=-1, cur=0):
    # If depth limit
    if depth >=0 and cur>depth:
        return None
    tag = e.tag
    obj = {}
    # attributes
    for k,v in e.attrib.items():
        obj['@' + k] = v
    # children
    children = list(e)
    if children:
        # group by tag
        for c in children:
            child_json = elem_to_json(c, depth, cur+1)
            if child_json is None:
                continue
            t = c.tag
            if t in obj:
                if isinstance(obj[t], list):
