            try:
                indent = int(v)
            except:
                indent = 2
        if o == '--tab':
            use_tabs = True
        if o in ('-q','--query'):
            query = v
        if o in ('-x','--xpath'):
            xpath_q = v
        if o in ('-e','--extract'):
            extract = v
        if o in ('-a','--attr'):
            attr = v
        if o in ('-d','--depth'):
            try:
                depth = int(v)
            except:
                depth = -1
    # read input
