        # parse xml
        try:
            root = ET.fromstring(input_text)
        except Exception as e:
            # try to wrap in a root
            try:
                root = ET.fromstring('<root>'+input_text+'</root>')
            except Exception:
                sys.stderr.write('Failed to parse XML input\n')
                return
        nodes = []
