        for it in out_items:
            sys.stdout.write(it)
            if not it.endswith('\n'):
                sys.stdout.write('\n')
        return
    # JSON output
    if as_json:
        j = xml_to_json(input_text, depth)
        if j is None:
            sys.stderr.write('Failed to parse XML to JSON\n')
            return
